"use client";
import { ChevronDown, ChevronUp } from 'lucide-react'
import React, { useMemo, useState } from 'react'
import PrimaryBtn from '@/components/PrimaryBtn'
import type { ConfirmLocationsData } from '@/types/chat'
import { Box, Flex, ScrollArea, Text, TextInput } from '@mantine/core'
import { motion, AnimatePresence } from 'framer-motion'
import SecondaryActionIcon from '@/components/SecondaryActionIcon'
import { WidgetLayout } from '../../chat/components'

interface WidgetGlassMorphismProps {
  content: ConfirmLocationsData
  onConfirm?: (value: string | number) => void
  aiText?: React.ReactNode
  showLogo?: boolean
  isLatest?: boolean
}

const svgMap = `<svg width="1202" height="609" viewBox="0 0 1202 609" fill="none" xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink">
<rect x="0.406764" y="0.406764" width="1201.19" height="608.186" rx="9.35558" fill="url(#pattern0_4640_4366)" stroke="#272727" stroke-width="0.813528"/>
<defs>
<pattern id="pattern0_4640_4366" patternContentUnits="objectBoundingBox" width="1" height="1">
<use xlink:href="#image0_4640_4366" transform="matrix(0.000937358 0 0 0.00185009 0 -0.256686)"/>
</pattern>
<image id="image0_4640_4366" width="1247" height="818" preserveAspectRatio="none" xlink:href="data:image/png;base64,"/>
</defs>
</svg>
`

export default function WidgetGlassMorphism({
  content,
  onConfirm,
  aiText,
  showLogo = false,
  isLatest = true,
}: WidgetGlassMorphismProps) {
  const [title, setTitle] = useState('')
  const [removedIndices, setRemovedIndices] = useState<Set<number>>(new Set())
  const [open, setOpen] = useState(isLatest)
  const [prevIsLatest, setPrevIsLatest] = useState(isLatest)

  if (isLatest !== prevIsLatest) {
    setPrevIsLatest(isLatest)
    if (!isLatest) {
      setOpen(false)
    }
  }

  const allLocations = useMemo(() => {
    return content.locations.map((loc) => ({
      name: loc.location_name || loc.name || 'Location',
      address: loc.formatted_address || '',
    }))
  }, [content.locations])

  const activeLocations = useMemo(() => {
    return allLocations.filter((_, i) => !removedIndices.has(i))
  }, [allLocations, removedIndices])

  const handleRemove = (originalIndex: number) => {
    setRemovedIndices((prev) => {
      const next = new Set(prev)
      next.add(originalIndex)
      return next
    })
  }

  const primaryLocation = allLocations[0]

  const backgroundUrl =
    typeof window !== 'undefined'
      ? `url("data:image/svg+xml;base64,${window.btoa(unescape(encodeURIComponent(svgMap)))}")`
      : ''

  return (
    <>
      <WidgetLayout mode="full" aiText={aiText} showLogo={showLogo}>
        <Box
          className="border-stroke-widget relative h-[65dvh] w-full overflow-hidden rounded-lg border-2 md:h-150 lg:h-[64dvh]"
          style={{
            backgroundImage: backgroundUrl,
            backgroundSize: 'cover',
            backgroundPosition: 'center',
          }}
        >
          {/* Floating Collapsible Widget */}
          <AnimatePresence>
            <motion.div
              initial={{ opacity: 0, scale: 0.95, y: -10 }}
              animate={{ opacity: 1, scale: 1, y: 0 }}
              exit={{ opacity: 0, scale: 0.95, y: -10 }}
              transition={{ duration: 0.2 }}
              className="absolute top-2 right-2 left-2 z-100 w-auto max-w-full origin-top-right sm:left-auto sm:w-80 sm:max-w-[calc(100%-1rem)]"
            >
              <motion.div
                layout
                transition={{
                  type: 'spring',
                  damping: 20,
                  stiffness: 300,
                  mass: 1,
                }}
                className="border-stroke-widget shadow-[0_2px_3px_0_rgba(0, 0, 0, 0.06)] dark:[#30302E] rounded-[28px]! bg-[#30302E]/65"
              >
                <button
                  type="button"
                  onClick={() => setOpen(!open)}
                  className="w-full p-1 text-left"
                >
                  {/* Header */}
                  <Box className="text-primary-text! mx-0.5! my-0.5 cursor-pointer rounded-[26px]! border-[0.5px] border-[#3D3D3A]/7 bg-[#1B1B1B]/3 p-2! backdrop-blur-[7.7px] transition-colors duration-150 ease-out">
                    <Flex justify={'space-between'} align={'center'}>
                      {/* Location Icon */}
                      <Flex gap={'0.5rem'} align={'center'}>
                        <Box
                          className={
                            'flex h-8 w-8 shrink-0 items-center justify-center rounded-full'
                          }
                          style={{
                            background: 'rgba(255,255,255,0.06)',
                            boxShadow: `inset -3px -5px 2.5px -5px #FFFFFF,
                                        inset 2.5px 3.5px 2px -3.5px #FFFFFF`,
                          }}
                        >
                          <svg
                            width="16"
                            height="16"
                            viewBox="0 0 16 16"
                            fill="none"
                            xmlns="http://www.w3.org/2000/svg"
                          >
                            <path
                              d="M11.8129 2.03287C11.1213 1.46658 10.3126 1.06084 9.44521 0.844911C8.5778 0.628982 7.67329 0.60825 6.7969 0.784208C5.67005 1.01523 4.63336 1.56531 3.81032 2.36891C2.98728 3.1725 2.41259 4.19575 2.15469 5.31675C1.8968 6.43776 1.96658 7.60927 2.35572 8.69174C2.74486 9.7742 3.43696 10.722 4.34957 11.4222C5.39152 12.1848 6.27867 13.1389 6.96357 14.2335L7.43023 15.0095C7.4895 15.1081 7.57326 15.1897 7.67338 15.2463C7.77349 15.3029 7.88655 15.3327 8.00157 15.3327C8.11658 15.3327 8.22964 15.3029 8.32975 15.2463C8.42987 15.1897 8.51363 15.1081 8.5729 15.0095L9.02023 14.2642C9.61664 13.2158 10.4299 12.3067 11.4056 11.5975C12.1706 11.0712 12.8029 10.3742 13.2525 9.56163C13.7021 8.74906 13.9568 7.84313 13.9963 6.91532C14.0359 5.9875 13.8593 5.06319 13.4805 4.2153C13.1017 3.36741 12.531 2.61914 11.8136 2.02954L11.8129 2.03287ZM8.0009 9.33354C7.47348 9.33354 6.95791 9.17715 6.51938 8.88413C6.08085 8.59111 5.73905 8.17463 5.53722 7.68736C5.33539 7.2001 5.28258 6.66392 5.38547 6.14663C5.48837 5.62935 5.74234 5.1542 6.11528 4.78126C6.48822 4.40832 6.96338 4.15434 7.48066 4.05145C7.99794 3.94855 8.53412 4.00136 9.02139 4.2032C9.50866 4.40503 9.92513 4.74682 10.2182 5.18535C10.5112 5.62389 10.6676 6.13946 10.6676 6.66688C10.6676 7.37412 10.3866 8.0524 9.88652 8.55249C9.38642 9.05259 8.70814 9.33354 8.0009 9.33354Z"
                              fill="#FAF9F5"
                            />
                          </svg>
                        </Box>

                        <Box>
                          <Text className="font-semibold! text-white!">
                            Location Confirmation
                          </Text>
                          <Text className="text-sm! text-white/80!">
                            {primaryLocation?.address ||
                              'San Francisco, CA, USA'}
                          </Text>
                        </Box>
                      </Flex>

                      <Box>
                        <div className="my-auto shrink-0 text-white">
                          {open ? (
                            <ChevronUp size={20} />
                          ) : (
                            <ChevronDown size={20} />
                          )}
                        </div>
                      </Box>
                    </Flex>
                  </Box>
                </button>

                <AnimatePresence initial={false}>
                  {open && (
                    <motion.div
                      initial={{ height: 0, opacity: 0 }}
                      animate={{ height: 'auto', opacity: 1 }}
                      exit={{ height: 0, opacity: 0 }}
                      transition={{ duration: 0.2, ease: 'easeInOut' }}
                      className="overflow-hidden"
                    >
                      <Box className="flex flex-col py-3.5">
                        {/* New Title Input Section */}
                        <Box className="mb-4 px-4">
                          <Text fz={12} fw={500} className="mb-2.5! text-white">
                            New Title
                          </Text>
                          <TextInput
                            value={title}
                            onChange={(e) => setTitle(e.currentTarget.value)}
                            placeholder="Add title here....."
                            disabled={!isLatest}
                            styles={{
                              input: {
                                background: 'rgba(27, 27, 27, 0.1)',
                                border: 'none',
                                borderRadius: 35,
                                color: '#fff',
                                height: '36px',
                                fontSize: '13px',
                              },
                            }}
                            classNames={{
                              input:
                                'placeholder:text-white! placeholder:opacity-100!',
                            }}
                            className="rounded-[35px]! shadow-[0_1px_1.5px_rgba(44,54,53,0.025),inset_0_-2px_0_rgba(0,0,0,0.04)]! backdrop-blur-[5.2px]!"
                          />
                        </Box>

                        <Box className="px-4">
                          <div>
                            <div className="mb-2.5 flex items-center justify-end gap-3">
                              <span className="text-sm font-semibold text-white">
                                Confirmed Locations
                              </span>
                            </div>

                            <ScrollArea
                              scrollbars="y"
                              h={
                                activeLocations.length <= 3
                                  ? (158 / 3) * activeLocations.length
                                  : 158
                              }
                              type="auto"
                              scrollbarSize={2}
                              className="mb-2.5 rounded-md bg-[#1B1B1B]/3 backdrop-blur-[7.7px]"
                            >
                              {activeLocations.length < 1 ? (
                                <div className="border-underline/30 flex items-center justify-between gap-3 border-b px-3 last:border-none">
                                  <div className="flex flex-col items-start justify-center py-2">
                                    <span className="text-sm font-normal text-white">
                                      No Locations Selected
                                    </span>
                                  </div>
                                </div>
                              ) : (
                                activeLocations.map((loc, idx) => {
                                  const originalIndex = allLocations.findIndex(
                                    (l) =>
                                      l.name === loc.name &&
                                      l.address === loc.address,
                                  )
                                  return (
                                    <div
                                      key={`${loc.name}-${idx}`}
                                      className="flex items-center justify-between gap-3 border-b border-white/60 px-3 last:border-none"
                                    >
                                      <div className="flex flex-col items-start justify-center py-2">
                                        <span
                                          className="max-w-54 truncate text-xs font-semibold text-white"
                                          title={loc.name}
                                        >
                                          {loc.name}
                                        </span>
                                        <span className="text-sm font-normal text-white/70">
                                          {loc.address}
                                        </span>
                                      </div>
                                      <Box
                                        className={
                                          'flex shrink-0 items-center justify-center rounded-[6px]'
                                        }
                                        style={{
                                          background: 'rgba(255,255,255,0.06)',
                                          boxShadow: `inset -3px -5px 2.5px -5px #FFFFFF,
                                                      inset 2.5px 3.5px 2px -3.5px #FFFFFF`,
                                        }}
                                      >
                                        <SecondaryActionIcon
                                          size="xs"
                                          radius={4}
                                          disabled={!isLatest}
                                          className="bg-transparent! hover:bg-white/10!"
                                          onClick={() =>
                                            handleRemove(originalIndex)
                                          }
                                        >
                                          <svg
                                            width="20"
                                            height="20"
                                            viewBox="0 0 20 20"
                                            fill="none"
                                            xmlns="http://www.w3.org/2000/svg"
                                          >
                                            <rect
                                              width="20"
                                              height="20"
                                              rx="6"
                                              fill="white"
                                              fillOpacity="0.1"
                                            />
                                            <path
                                              d="M5.91602 10H14.0827"
                                              stroke="#FBFBFB"
                                              strokeWidth="2"
                                              strokeLinecap="round"
                                              strokeLinejoin="round"
                                            />
                                          </svg>
                                        </SecondaryActionIcon>
                                      </Box>
                                    </div>
                                  )
                                })
                              )}
                            </ScrollArea>
                          </div>
                        </Box>

                        <Box className="border-underline/10 border-t px-4">
                          <Text
                            className="mb-4! text-sm! leading-tight! font-medium! text-white"
                            style={{ lineHeight: '1.45' }}
                          >
                            Deselect any you don&apos;t want, or proceed to find
                            everyone who&apos;s been there recently?
                          </Text>
                          <Box className="flex! justify-end!">
                            <Box
                              className={
                                'flex shrink-0 items-center justify-center rounded-[21px]!'
                              }
                              style={{
                                background: 'rgba(255,255,255,0.06)',
                                boxShadow: `inset -3px -5px 2.5px -5px #FFFFFF,
                                            inset 2.5px 3.5px 2px -3.5px #FFFFFF`,
                              }}
                            >
                              <PrimaryBtn
                                className="rounded-[21px]! border! bg-[rgba(255,255,255,0.1)]! shadow-[inset_0_3px_0_rgba(255,255,255,0.25)]! hover:bg-[rgba(255,255,255,.20)]! hover:shadow-[inset_0_3px_0_rgba(255,255,255,0.25)]!"
                                onClick={() =>
                                  isLatest && onConfirm?.('confirmed')
                                }
                                disabled={!isLatest}
                              >
                                Confirm
                              </PrimaryBtn>
                            </Box>
                          </Box>
                        </Box>
                      </Box>
                    </motion.div>
                  )}
                </AnimatePresence>
              </motion.div>
            </motion.div>
          </AnimatePresence>
        </Box>
      </WidgetLayout>
    </>
  )
}
